module aqueduct_solver (input clk, input rst_n, input start, input [11:0] hill_x [0:3], input [11:0] hill_y [0:3], input [11:0] hill_h [0:3], input [1:0] spring_idx [0:1], input [1:0] town_idx [0:1], input [15:0] q_max, output reg [31:0] min_length, output reg done, output reg valid); function [31:0] sqrt_func; input [31:0] x; begin sqrt_func = x; sqrt_func = (sqrt_func + x / sqrt_func) >> 1; sqrt_func = (sqrt_func + x / sqrt_func) >> 1; sqrt_func = (sqrt_func + x / sqrt_func) >> 1; sqrt_func = (sqrt_func + x / sqrt_func) >> 1; sqrt_func = (sqrt_func + x / sqrt_func) >> 1; sqrt_func = (sqrt_func + x / sqrt_func) >> 1; end endfunction wire [11:0] dx00, dy00, dx01, dy01, dx10, dy10, dx11, dy11; wire [23:0] sq_dist00, sq_dist01, sq_dist10, sq_dist11; wire [31:0] dist00, dist01, dist10, dist11; wire valid00, valid01, valid10, valid11; reg [1:0] state; reg [31:0] min_length_reg; reg done_reg, valid_reg; always @(*) begin dx00 = hill_x[spring_idx[0]] - hill_x[town_idx[0]]; dy00 = hill_y[spring_idx[0]] - hill_y[town_idx[0]]; sq_dist00 = dx00*dx00 + dy00*dy00; dist00 = sqrt_func({24{0}, sq_dist00}); valid00 = hill_h[spring_idx[0]] >= hill_h[town_idx[0]]; dx01 = hill_x[spring_idx[0]] - hill_x[town_idx[1]]; dy01 = hill_y[spring_idx[0]] - hill_y[town_idx[1]]; sq_dist01 = dx01*dx01 + dy01*dy01; dist01 = sqrt_func({24{0}, sq_dist01}); valid01 = hill_h[spring_idx[0]] >= hill_h[town_idx[1]]; dx10 = hill_x[spring_idx[1]] - hill_x[town_idx[0]]; dy10 = hill_y[spring_idx[1]] - hill_y[town_idx[0]]; sq_dist10 = dx10*dx10 + dy10*dy10; dist10 = sqrt_func({24{0}, sq_dist10}); valid10 = hill_h[spring_idx[1]] >= hill_h[town_idx[0]]; dx11 = hill_x[spring_idx[1]] - hill_x[town_idx[1]]; dy11 = hill_y[spring_idx[1]] - hill_y[town_idx[1]]; sq_dist11 = dx11*dx11 + dy11*dy11; dist11 = sqrt_func({24{0}, sq_dist11}); valid11 = hill_h[spring_idx[1]] >= hill_h[town_idx[1]]; end always @(posedge clk) begin if (!rst_n) begin state <= 2'b00; min_length_reg <= 32'hFFFFFFFF; done_reg <= 1'b0; valid_reg <= 1'b0; end else begin case (state) 2'b00: if (start) begin state <= 2'b01; min_length_reg <= 32'hFFFFFFFF; done_reg <= 1'b0; valid_reg <= 1'b0; end else begin state <= 2'b00; end 2'b01: state <= 2'b10; 2'b10: wire [31:0] perm0_total, perm1_total; wire valid_perm0, valid_perm1; valid_perm0 = valid00 && valid11 && (dist00 <= q_max) && (dist11 <= q_max); perm0_total = valid_perm0 ? (dist00 + dist11) : 32'hFFFFFFFF; valid_perm1 = valid01 && valid10 && (dist01 <= q_max) && (dist10 <= q_max); perm1_total = valid_perm1 ? (dist01 + dist10) : 32'hFFFFFFFF; wire [31:0] min_total; wire valid_any = valid_perm0 || valid_perm1; if (valid_any) begin if (valid_perm0 && valid_perm1) begin min_total = (perm0_total < perm1_total) ? perm0_total : perm1_total; end else if (valid_perm0) begin min_total = perm0_total; end else begin min_total = perm1_total; end end else begin min_total = 32'hFFFFFFFF; end min_length_reg <= min_total; done_reg <= 1'b1; valid_reg <= valid_any; state <= 2'b11; 2'b11: state <= 2'b11; endcase end end end assign min_length = min_length_reg; assign done = done_reg; assign valid = valid_reg; endmodule